scwin.fn_listGrntFeeApproval = function() {
    var argv = fn_listGrntFeeApproval.arguments;
    var argc = fn_listGrntFeeApproval.arguments.length;
    $c.cm.ShowWin(grd_Grid);
    /*
    var url = "/StdCdListIDChgAction.do?method=listGrntFeeApproval";
    	url += "&ISUR_CD=" + getObjectValue(txb_ISUR_CD);  	
    	url += "&SDATE=" + getObjectValue(edt_SDATE);       
    	url += "&EDATE=" + getObjectValue(edt_EDATE);      
    	url += "&APPL_RSLT=" + getObjectValue(cmb_APPL_RSLT);
    	url += "&SCREN_ID=" + vScrenID;
    	url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    */
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=GRNTFEEAPPROVALLIST_21400_INOUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.etc.select.listGrntFeeApproval.dyn" + "&{P}ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD) + "&{P}SDATE=" + $c.stf.getObjectValue(edt_SDATE) + "&{P}EDATE=" + $c.stf.getObjectValue(edt_EDATE) + "&{P}APPL_RSLT=" + $c.stf.getObjectValue(cmb_APPL_RSLT);

    //alert(url);
    dts_PassList.DataID = encodeURI(url);
    dts_PassList.Reset();
};
scwin.fn_SetCode = function() {
    $c.stf.setObjectValue(cmb_APPL_RSLT, "R");

    // 승인구분코드 셋팅
    ins_combo_set(dts_ApplRsltCd, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "00738", "SEL"); //신청결과코드 

};
scwin.arrPar = new Array();
/********************************************** 
 * 함수명   : fn_GetParam
 * 설명       : 전달값을 설정한다.
 ***********************************************/
scwin.fn_GetParam = function(arrPar) {
    scwin.arrPar[0] = txb_param1.getValue(); // 발행기관코드  
    scwin.arrPar[1] = txb_param2.getValue(); // 발행기관코드명     

    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    scwin.arrPar, length;
};
scwin.fn_readGrntFeeApproval = async function(row, colid) {
    if (colid == "STD_CD_APCT_ID") {
        var vROW = row; //ROW 임의지정
        await $c.frame.CreateDialogFrame("ROW=" + vROW, "/etc/ULDINS21401.gfm", "수수료안내공문 신청 상세정보", 10, 10, 580, 490, "window");
    }
    /*
		else if (colid == "COM_NM") {
			if (row == 0) return; 
			txb_param1.value = dts_PassList.NameValue(row,"ISUR_CD");// 발행기관코드  
			txb_param2.value = dts_PassList.NameValue(row,"COM_NM"); // 발행기관명    
			fn_GetPar = fn_GetParam;
			ins_popupOpen("","","ULDINS91600","발행기관 상세정보","1220","730");	
		} */
};
scwin.btn_Search_onclick = function() {
    scwin.fn_listGrntFeeApproval();
};
scwin.btn_SDATE_onclick = function() {
    popUpCalendar2(edt_SDATE);
};
scwin.btn_EDATE_onclick = function() {
    popUpCalendar2(edt_EDATE);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.stf.getObjectValue(cmb_PeriodTp);
    $c.stf.fn_setFromToDate(vTp, edt_SDATE, edt_EDATE);
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07, '');
    $c.data.downloadGridViewExcel(grd_Grid, "수수료안내공문신청목록", "", "8");
};
scwin.dts_PassList_OnLoadCompleted = function(rowcount) {
    if (dts_PassList.errorMsg) {
        $c.win.alert(dts_PassList.errorMsg);
    } else {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    }
    $c.cm.CloseWin(rowcount, grd_Grid);
};
scwin.dts_PassList_OnLoadError = function() {
    $c.stf.alert_error(dts_PassList);
};
scwin.grd_Grid_OnDblClick = function(row, colid) {
    scwin.fn_readGrntFeeApproval(row, colid);
};
scwin.txb_ISUR_CD_onkeypress = function() {
    if (window.event.keyCode == 13) scwin.fn_listGrntFeeApproval();
};
scwin.txb_ISU_CD_onkeypress = function() {
    if (window.event.keyCode == 13) scwin.fn_listGrntFeeApproval();
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
scwin.gform_onload = function() {
    $c.stf.showObj(txb_param1, false);
    $c.stf.showObj(txb_param2, false);
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_SetCode();
    scwin.fn_Init();
    scwin.fn_listGrntFeeApproval();
};
